let wordLimit = 12; // Начальный лимит слов

// Функция для проверки введенных слов
function checkCombination() {
  const enteredWords = $('.modal_nonweb_main_blocks_item_input').map(function() {
      return $(this).val().trim().toLowerCase();
  }).get().slice(0, wordLimit); // Берем только первые wordLimit слов
  
  console.log(enteredWords)
  // Проверка на валидность слов
  const allWordsValid = enteredWords.every(word => 
      wordDatabase.some(dbWord => dbWord.toLowerCase() === word)
  );

  // Если все слова валидны и их количество соответствует лимиту
  if (allWordsValid) {
    console.log("valid")
      sendbutton.addClass('modal_nonweb_button_active');
      sendbutton.text('Continue');
      sendbutton.prop('disabled', false); // Убираем disable
      //sendbutton.onClick(sendWords())
  } else {
    console.log("non valid")
      sendbutton.removeClass('modal_nonweb_button_active');
      sendbutton.text('Missing words');
      sendbutton.prop('disabled', true); // Включаем disable
  }
}

// Функция для зачеркивания неподходящих слов
function markInvalidWords($input) {
  const word = $input.val().trim().toLowerCase();
  const isWordValid = wordDatabase.includes(word);

  if (!isWordValid) {
      $input.css({
          'text-decoration': 'solid line-through red 2px',
      }); // Зачеркиваем слово
  } else {
      $input.css({
          'text-decoration': 'none',
      }); // Убираем зачеркивание, если слово валидно
  }
}

